import re

txt = context

def extract_section(name):
    start = txt.find(f"=== {name} ===")
    end = txt.find(f"=== End {name} ===")
    if start == -1 or end == -1:
        return ""
    return txt[start:end]

sec_requests = extract_section("Shipment Requests")
sec_inventory = extract_section("Warehouse Inventory")
sec_quality = extract_section("Quality Release")
sec_holds = extract_section("Dispatch Holds")
sec_archived = extract_section("Archived Shipments")

print("Sections lengths:", len(sec_requests), len(sec_inventory), len(sec_quality), len(sec_holds), len(sec_archived))

# Parse sections
req_pattern = re.compile(r'^(R-\d+)\s*\|\s*(?:Request\s+)?(SH-\d+).*?(\d+)\s+units', re.M)
inv_pattern = re.compile(r'^(W-\d+)\s*\|.*?(SH-\d+).*?(\d+)\s+units', re.M)
qual_pattern = re.compile(r'^(Q-\d+)\s*\|.*?(SH-\d+).*?\b(APPROVED|PENDING|REJECTED)\b', re.M)
hold_pattern = re.compile(r'^(H-\d+)\s*\|.*?(SH-\d+).*?\b(NONE|ACTIVE)\b', re.M)

requests = {}
for sid, sh, qty in req_pattern.findall(sec_requests):
    requests[sh] = {"request_id": sid, "requested_qty": int(qty)}

inventory = {}
for wid, sh, qty in inv_pattern.findall(sec_inventory):
    inventory[sh] = {"inventory_id": wid, "available_qty": int(qty)}

quality = {}
for qid, sh, status in qual_pattern.findall(sec_quality):
    quality[sh] = {"quality_id": qid, "quality_status": status}

holds = {}
for hid, sh, status in hold_pattern.findall(sec_holds):
    holds[sh] = {"hold_id": hid, "hold_status": status}

print("Parsed counts:", len(requests), len(inventory), len(quality), len(holds))

# Join and filter
all_sh_ids = set(requests) & set(inventory) & set(quality) & set(holds)
print("Joined shipment IDs count:", len(all_sh_ids))

eligible = []
for sh in all_sh_ids:
    rq = requests[sh]["requested_qty"]
    av = inventory[sh]["available_qty"]
    qs = quality[sh]["quality_status"]
    hs = holds[sh]["hold_status"]
    if rq > 0 and av >= rq and qs == "APPROVED" and hs == "NONE":
        eligible.append({
            "shipment_id": sh,
            "requested_qty": rq,
            "available_qty": av,
            "request_id": requests[sh]["request_id"],
            "inventory_id": inventory[sh]["inventory_id"],
            "quality_id": quality[sh]["quality_id"],
            "hold_id": holds[sh]["hold_id"],
        })

print("Eligible count:", len(eligible))

def sh_numeric(sh):
    # sh like SH-10156 -> 10156
    return int(sh.split("-")[1])

eligible_sorted = sorted(eligible, key=lambda x: (-x["requested_qty"], sh_numeric(x["shipment_id"])))

# Preview top 5
for item in eligible_sorted[:5]:
    print(item)

# Compute combined for top 3
top3 = eligible_sorted[:3]
combined = sum(x["requested_qty"] for x in top3)
print("Combined requested (top3):", combined)

